# === file: lib/request.php ===
<?php
/**
 * Helper that is now actually defensive: input shaping PLUS
 * synchronizer-token CSRF verification and Origin/Referer validation.
 */
class RequestUtil
{
    public static function getIntParam($key)
    {
        $raw = isset($_REQUEST[$key]) ? $_REQUEST[$key] : '';
        $clean = intval(strip_tags(trim($raw))); // value shaping only
        return $clean;
    }

    /**
     * [DEFENSE] Per-session synchronizer token (Synchronizer Token Pattern).
     * Generated once per session; pages that render the delete control must
     * embed this value so state-changing requests can prove intent.
     */
    public static function getCsrfToken()
    {
        if (empty($_SESSION['csrf_token'])) {
            $_SESSION['csrf_token'] = bin2hex(random_bytes(32));
        }
        return $_SESSION['csrf_token'];
    }

    /**
     * [DEFENSE] Timing-safe comparison of the submitted token against the
     * session-stored token; rejects missing, empty or mismatched values.
     */
    public static function verifyCsrfToken($token)
    {
        $expected = self::getCsrfToken();
        return is_string($token)
            && $token !== ''
            && hash_equals($expected, $token);
    }

    /**
     * [DEFENSE] Second layer: exact allow-list on the Origin/Referer host.
     * Cross-site attackers cannot forge these headers from a browser.
     */
    public static function verifySameOrigin()
    {
        $allowed = $_SERVER['HTTP_HOST'];
        $header = '';
        if (!empty($_SERVER['HTTP_ORIGIN'])) {
            $header = $_SERVER['HTTP_ORIGIN'];
        } elseif (!empty($_SERVER['HTTP_REFERER'])) {
            $header = $_SERVER['HTTP_REFERER'];
        } else {
            return false; // no origin proof at all -> reject
        }
        $host = parse_url($header, PHP_URL_HOST);
        return is_string($host) && strcasecmp($host, $allowed) === 0;
    }
}

