package org.apache.camel.component.infinispan.remote.protostream;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.InvalidClassException;
import java.io.ObjectStreamClass;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Date;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.Set;
import java.util.UUID;

import org.apache.camel.support.DefaultExchangeHolder;
import org.apache.camel.util.ClassLoadingAwareObjectInputStream;

/** Marshalling helpers for {@link DefaultExchangeHolder} over Protostream transports. */
final class DefaultExchangeHolderUtils {

    /**
     * Exact allow-set of every class name that may be resolved while reading
     * a serialized DefaultExchangeHolder. Any other class name is rejected
     * before it is loaded or instantiated, so known gadget chains cannot run.
     */
    private static final Set<String> ALLOWED_CLASSES = buildAllowedClasses();

    private DefaultExchangeHolderUtils() {
    }

    public static DefaultExchangeHolder deserialize(byte[] bytes) throws IOException {
        try (ByteArrayInputStream bais = new ByteArrayInputStream(bytes);
             WhitelistObjectInputStream ois = new WhitelistObjectInputStream(bais)) {
            return (DefaultExchangeHolder) ois.readObject();
        } catch (ClassNotFoundException e) {
            throw new IOException(e);
        }
    }

    private static Set<String> buildAllowedClasses() {
        Set<String> allowed = new HashSet<>();
        allowed.add(DefaultExchangeHolder.class.getName());
        allowed.add(String.class.getName());
        allowed.add(byte[].class.getName());
        allowed.add(Boolean.class.getName());
        allowed.add(Character.class.getName());
        allowed.add(Byte.class.getName());
        allowed.add(Short.class.getName());
        allowed.add(Integer.class.getName());
        allowed.add(Long.class.getName());
        allowed.add(Float.class.getName());
        allowed.add(Double.class.getName());
        allowed.add(BigInteger.class.getName());
        allowed.add(BigDecimal.class.getName());
        allowed.add(Date.class.getName());
        allowed.add(UUID.class.getName());
        allowed.add(HashMap.class.getName());
        allowed.add(LinkedHashMap.class.getName());
        allowed.add(ArrayList.class.getName());
        return Collections.unmodifiableSet(allowed);
    }

    /**
     * ObjectInputStream that resolves classes only from ALLOWED_CLASSES.
     * Regular classes and dynamic proxy interfaces are both checked, so no
     * gadget class is ever loaded or instantiated during readObject.
     */
    private static final class WhitelistObjectInputStream extends ClassLoadingAwareObjectInputStream {

        WhitelistObjectInputStream(InputStream in) throws IOException {
            super(in);
        }

        @Override
        protected Class<?> resolveClass(ObjectStreamClass desc) throws IOException, ClassNotFoundException {
            if (!ALLOWED_CLASSES.contains(desc.getName())) {
                throw new InvalidClassException("Rejected class outside whitelist: " + desc.getName());
            }
            return super.resolveClass(desc);
        }

        @Override
        protected Class<?> resolveProxyClass(String[] interfaces) throws IOException, ClassNotFoundException {
            for (String iface : interfaces) {
                if (!ALLOWED_CLASSES.contains(iface)) {
                    throw new InvalidClassException("Rejected proxy interface outside whitelist: " + iface);
                }
            }
            return super.resolveProxyClass(interfaces);
        }
    }
}

