# === file: src/Parser/MathmlParser.php ===
<?php
declare(strict_types=1);

namespace App\Parser;

use DOMDocument;
use DOMXPath;
use InvalidArgumentException;

/**
 * Minimal MathML walker.
 * Security: entity/DTD handling is enforced HERE, centrally, for every caller.
 * MathML content never requires a DTD, so any DOCTYPE/ENTITY construct is
 * rejected and the parser itself runs with external loading fully disabled.
 */
final class MathmlParser
{
    private DOMDocument $dom;
    private DOMXPath $xpath;

    public function parse(string $content): array
    {
        // Layer 1: structural gate — a conformant MathML document is DTD-free.
        // Reject DOCTYPE/ENTITY up front so neither external subsets nor
        // internal entity graphs (billion-laughs) can ever be registered.
        if (preg_match('/<!\s*(DOCTYPE|ENTITY)/i', $content)) {
            throw new InvalidArgumentException('DTD or entity declarations are not allowed in MathML input');
        }

        // Layer 2: parser hardening — no DTD subset loading, no network fetches,
        // no entity substitution. Even if a crafted document bypassed layer 1,
        // libxml cannot resolve SYSTEM/PUBLIC identifiers to file:// or http://.
        $this->dom = new DOMDocument();
        $this->dom->loadXML($content, LIBXML_NONET);
        $this->xpath = new DOMXPath($this->dom);

        $names = [];
        foreach ($this->xpath->query('//*') ?: [] as $node) {
            $names[] = $node->nodeName;
        }
        return $names;
    }
}

