public class ProxyService {
    private static final Set<String> ALLOWED_HOSTS = Set.of("api.example.com", "cdn.example.com");

    public String fetch(String targetUrl) throws Exception {
        URL endpoint_url = new URL(targetUrl);
        if (!endpoint_url.getProtocol().matches("https?") || !ALLOWED_HOSTS.contains(endpoint_url.getHost())) {
            throw new IllegalArgumentException("URL not allowed");
        }
        HttpURLConnection conn = (HttpURLConnection) endpoint_url.openConnection();
        conn.setConnectTimeout(5000);
        conn.setInstanceFollowRedirects(false);
        try (BufferedReader br = new BufferedReader(new InputStreamReader(conn.getInputStream()))) {
            StringBuilder sb = new StringBuilder();
            String line;
            while ((line = br.readLine()) != null) sb.append(line);
            return sb.toString();
