import requests
from flask import Flask, request, Response
from urllib.parse import urlparse
import ipaddress

app = Flask(__name__)

ALLOWED_SCHEMES = {'http', 'https'}

def is_safe_url(endpoint_url):
    p = urlparse(endpoint_url)
    if p.scheme not in ALLOWED_SCHEMES or not p.hostname:
        return False
    try:
        ip = ipaddress.ip_address(p.hostname)
        if ip.is_private or ip.is_loopback or ip.is_reserved:
            return False
    except ValueError:
        pass  # 域名，做 DNS 解析后再次校验
    return True

@app.route('/proxy')
def proxy():
    endpoint_url = request.args.get('endpoint_url')
    if not is_safe_url(endpoint_url):
        return 'forbidden', 403
    resp = requests.get(endpoint_url, timeout=5, allow_redirects=False)
    return Response(resp.content, status=resp.status_code)

